{
  "name": "pydantic-skills",
  "interface": {
    "displayName": "Pydantic"
  },
  "plugins": [
    {
      "name": "logfire",
      "source": {
        "source": "local",
        "path": "./plugins/logfire"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Coding"
    },
    {
      "name": "logfire-exporter",
      "source": {
        "source": "local",
        "path": "./plugins/logfire-exporter"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Coding"
    }
  ]
}

{
  "mcpServers": {
    "logfire": {
      "type": "http",
      "url": "${LOGFIRE_MCP_URL:-https://logfire-us.pydantic.dev/mcp}"
    }
  }
}

{
  "$schema": "https://cursor.com/schemas/mcp.json",
  "mcpServers": {
    "logfire": {
      "type": "http",
      "url": "https://logfire-us.pydantic.dev/mcp",
      "description": "Hosted Logfire MCP server for querying traces, logs, spans, and project links."
    }
  }
}

{
  "mcpServers": {
    "logfire": {
      "type": "http",
      "url": "https://logfire-us.pydantic.dev/mcp"
    }
  }
}
